create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,points integer not null default 0,role text not null default 'user' check(role in('user','admin')),created_at timestamptz default now());
create table if not exists public.hypotheses(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,field text not null,body text not null,method text not null,experiment_count integer default 0,verified_count integer default 0,created_at timestamptz default now());
create table if not exists public.experiments(id uuid primary key default gen_random_uuid(),hypothesis_id uuid not null references public.hypotheses(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,result_text text not null,photo_url text,status text not null default 'pending' check(status in('pending','verified','rejected')),points_awarded integer default 0,created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.hypotheses enable row level security; alter table public.experiments enable row level security;
create policy "profiles public read" on public.profiles for select using(true);
create policy "hypotheses public read" on public.hypotheses for select using(true);
create policy "hypotheses own insert" on public.hypotheses for insert to authenticated with check(auth.uid()=user_id);
create policy "experiments own insert" on public.experiments for insert to authenticated with check(auth.uid()=user_id);
create policy "experiments read authenticated" on public.experiments for select to authenticated using(true);
insert into storage.buckets(id,name,public) values('experiment-evidence','experiment-evidence',true) on conflict(id) do nothing;
create policy "evidence public read" on storage.objects for select using(bucket_id='experiment-evidence');
create policy "evidence own upload" on storage.objects for insert to authenticated with check(bucket_id='experiment-evidence' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,username) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'username',''),split_part(new.email,'@',1)));return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.award_hypothesis_points() returns trigger language plpgsql security definer set search_path=public as $$begin update public.profiles set points=points+10 where id=new.user_id;return new;end;$$;
drop trigger if exists hypothesis_points on public.hypotheses;create trigger hypothesis_points after insert on public.hypotheses for each row execute procedure public.award_hypothesis_points();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin');$$;
create or replace function public.approve_experiment(p_experiment_id uuid) returns void language plpgsql security definer set search_path=public as $$declare e public.experiments%rowtype;begin if not public.is_admin() then raise exception 'admin only';end if;select * into e from public.experiments where id=p_experiment_id for update;if e.id is null or e.status<>'pending' then raise exception 'invalid experiment';end if;update public.experiments set status='verified',points_awarded=50 where id=e.id;update public.profiles set points=points+50 where id=e.user_id;update public.hypotheses set experiment_count=experiment_count+1,verified_count=verified_count+1 where id=e.hypothesis_id;end;$$;
create or replace function public.reject_experiment(p_experiment_id uuid) returns void language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'admin only';end if;update public.experiments set status='rejected' where id=p_experiment_id and status='pending';end;$$;
revoke all on function public.approve_experiment(uuid) from public;revoke all on function public.reject_experiment(uuid) from public;grant execute on function public.approve_experiment(uuid) to authenticated;grant execute on function public.reject_experiment(uuid) to authenticated;